package pe.com.asistencia.attendance.domain;
import jakarta.persistence.*; import pe.com.asistencia.employee.domain.Employee; import java.time.Instant; import java.math.BigDecimal;
@Entity @Table(name="punches")
public class Punch {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="employee_id") private Employee employee; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="attendance_day_id") private AttendanceDay attendanceDay; @Column(name="occurred_at",nullable=false,updatable=false) private Instant occurredAt; @Column(name="created_at",insertable=false,updatable=false) private Instant recordedAt; @Enumerated(EnumType.STRING) @Column(name="punch_type",nullable=false,updatable=false) private PunchType type; @Column(nullable=false,updatable=false) private String channel; @Column(name="ip_address",updatable=false) private String ipAddress; @Column(name="device_identifier",updatable=false) private String deviceIdentifier; @Column(precision=10,scale=7,updatable=false) private BigDecimal latitude; @Column(precision=10,scale=7,updatable=false) private BigDecimal longitude; @Column(name="accuracy_meters",precision=8,scale=2,updatable=false) private BigDecimal accuracyMeters; @Column(name="wifi_bssid",length=32,updatable=false) private String wifiBssid; @Column(name="site_id",updatable=false) private Long siteId; @Column(name="created_by",updatable=false) private Long createdBy; @Column(name="reason_code",length=40,updatable=false) private String reasonCode; @Column(name="request_id",updatable=false) private Long requestId;
 protected Punch(){} public Punch(Employee e,AttendanceDay d,Instant at,PunchType type,String channel,String ip,String device,Double lat,Double lon,String wifiBssid){this(e,d,at,type,channel,ip,device,lat,lon,null,wifiBssid,null,null,null,null);}
 public Punch(Employee e,AttendanceDay d,Instant at,PunchType type,String channel,String ip,String device,Double lat,Double lon,Double accuracyMeters,String wifiBssid,Long siteId,Long createdBy,String reasonCode,Long requestId){employee=e;attendanceDay=d;occurredAt=at;this.type=type;this.channel=channel;ipAddress=ip;deviceIdentifier=device;latitude=lat==null?null:BigDecimal.valueOf(lat);longitude=lon==null?null:BigDecimal.valueOf(lon);this.accuracyMeters=accuracyMeters==null?null:BigDecimal.valueOf(accuracyMeters);this.wifiBssid=wifiBssid;this.siteId=siteId;this.createdBy=createdBy;this.reasonCode=reasonCode;this.requestId=requestId;}
 public Long getId(){return id;} public Instant getOccurredAt(){return occurredAt;} public Instant getRecordedAt(){return recordedAt;} public PunchType getType(){return type;} public String getChannel(){return channel;} public String getReasonCode(){return reasonCode;}
}
